#!/usr/bin/env python3
import os
import re
import html as html_lib
import subprocess
import requests
from typing import List

URLS = [
    ("Do Things that Don't Scale", "https://paulgraham.com/ds.html"),
    ("Founder Mode", "https://paulgraham.com/foundermode.html"),
]


def fetch_html(url: str) -> str:
    result = subprocess.run(["curl", "-L", "-s", url], capture_output=True, text=True)
    if result.returncode != 0:
        raise RuntimeError(f"curl failed for {url}: {result.stderr}")
    return result.stdout


def html_to_text(html: str) -> str:
    # Remove comments, scripts, and styles
    html = re.sub(r"(?is)<!--.*?-->", " ", html)
    html = re.sub(r"(?is)<script.*?>.*?</script>", " ", html)
    html = re.sub(r"(?is)<style.*?>.*?</style>", " ", html)
    # Preserve paragraph/line breaks
    html = re.sub(r"(?i)<br\s*/?>", "\n", html)
    html = re.sub(r"(?i)</p>", "\n", html)
    # Strip tags
    text = re.sub(r"(?is)<[^>]+>", " ", html)
    text = html_lib.unescape(text)
    # Remove footnote markers like [1] or [ 1 ]
    text = re.sub(r"\[\s*\d+\s*\]", "", text)
    # Normalize whitespace
    text = re.sub(r"[ \t]+", " ", text)
    text = re.sub(r"\n\s*\n+", "\n\n", text)
    return text.strip()


def clean_text_for_tts(text: str) -> str:
    text = re.sub(r"http[s]?://\S+", "", text)
    text = re.sub(r"\s+", " ", text)
    # Keep basic punctuation only
    text = re.sub(r"[^\w\s.,!?;:'\"()\-]", "", text)
    return text.strip()


def chunk_text(text: str, max_chars: int = 3500) -> List[str]:
    sentences = re.split(r"(?<=[.!?])\s+", text)
    chunks = []
    current = ""
    for sentence in sentences:
        if not sentence:
            continue
        if len(current) + len(sentence) + 1 <= max_chars:
            current += sentence + " "
        else:
            if current:
                chunks.append(current.strip())
            current = sentence + " "
    if current:
        chunks.append(current.strip())
    return chunks


def verify_content(text: str, expected_min_chars: int = 1000) -> None:
    if len(text) < expected_min_chars:
        print(f"WARNING: Content may be truncated ({len(text)} chars)")


def concatenate_audio(audio_files: List[str], output_path: str) -> bool:
    if not audio_files:
        return False
    list_file = "/tmp/audio_list.txt"
    with open(list_file, "w", encoding="utf-8") as f:
        for audio_file in audio_files:
            f.write(f"file '{audio_file}'\n")
    result = subprocess.run([
        "ffmpeg", "-y", "-f", "concat", "-safe", "0",
        "-i", list_file, "-c", "copy", output_path
    ], capture_output=True, text=True)
    if result.returncode != 0:
        print(result.stderr)
    for af in audio_files:
        try:
            os.unlink(af)
        except FileNotFoundError:
            pass
    try:
        os.unlink(list_file)
    except FileNotFoundError:
        pass
    return result.returncode == 0


def create_with_openai(text: str, output_path: str) -> bool:
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        print("OPENAI_API_KEY not set")
        return False
    chunks = chunk_text(text, max_chars=3500)
    audio_files = []
    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/chunk_{i:03d}.mp3"
        response = requests.post(
            "https://api.openai.com/v1/audio/speech",
            headers={
                "Authorization": f"Bearer {api_key}",
                "Content-Type": "application/json",
            },
            json={
                "model": "tts-1",
                "input": chunk,
                "voice": "onyx",
                "response_format": "mp3",
            },
            timeout=60,
        )
        if response.status_code == 200:
            with open(chunk_file, "wb") as f:
                f.write(response.content)
            audio_files.append(chunk_file)
            print(f"Generated chunk {i + 1}/{len(chunks)}")
        else:
            print(f"OpenAI TTS error: {response.status_code} - {response.text}")
            return False
    return concatenate_audio(audio_files, output_path)


def main() -> int:
    combined_sections = []
    for title, url in URLS:
        print(f"Fetching: {url}")
        html = fetch_html(url)
        text = html_to_text(html)
        verify_content(text)
        section = f"{title}. By Paul Graham.\n\n{text}"
        combined_sections.append(section)
    combined_text = "\n\n".join(combined_sections)
    combined_text = clean_text_for_tts(combined_text)
    print(f"Total text length: {len(combined_text)} characters")

    output_path = "/root/audiobook.mp3"
    if create_with_openai(combined_text, output_path):
        print(f"Audiobook created at {output_path}")
        return 0
    print("Failed to create audiobook")
    return 1


if __name__ == "__main__":
    raise SystemExit(main())
